function rxcss(){if(document.getElementById('rx-css'))return;const e=document.createElement('style');e.id='rx-css';e.textContent=RXCSS;document.head.appendChild(e)}
const RXL={what:['What this shows','Hii inaonyesha nini'],read:['How to read it','Jinsi ya kuisoma'],mean:['What it means for the business','Maana yake kwa biashara'],eg:['Worked example','Mfano halisi'],tour:['Guided tour','Ziara ya maelezo'],step:['Step %A of %B','Hatua %A kati ya %B'],next:['Next','Endelea'],prev:['Back','Rudi'],end:['Finish','Maliza'],close:['Close','Funga']};
function EXB(x){if(!x)return '';return `<div class="rxex"><div><small><i>1</i>${L(RXL.what)}</small><p>${L(x.w)}</p></div><div><small><i>2</i>${L(RXL.read)}</small><p>${L(x.r)}</p></div><div><small><i>3</i>${L(RXL.mean)}</small><p>${L(x.m)}</p></div>${x.e?`<div class="eg"><small>${L(RXL.eg)}</small><p>${L(x.e)}</p></div>`:''}</div>`}
// put the explainer right after the module's lead paragraph
function withEX(html,x){const i=html.indexOf('</p>');return i>0&&html.startsWith('<p class="ld">')?html.slice(0,i+4)+EXB(x)+html.slice(i+4):EXB(x)+html}
function heroStats(a){return `<div class="rxhs">${a.map(x=>`<div><b data-n="${x[0]}" data-f="${x[2]||''}">${x[2]==='tsh'?'TSh 0':'0'}</b><span>${x[1]}</span></div>`).join('')}</div>`}
function countUp(){document.querySelectorAll('.rxhs b[data-n]').forEach(b=>{const n=+b.dataset.n,f=b.dataset.f,t0=performance.now();const fmt=v=>f==='tsh'?'TSh '+(v/1e6).toFixed(1)+' m':Math.round(v).toLocaleString('en-US');
 const st=t=>{const k=Math.min(1,(t-t0)/1400),e=1-Math.pow(1-k,3);b.textContent=fmt(n*e);if(k<1)requestAnimationFrame(st)};requestAnimationFrame(st)})}
let RXT=null;
function tour(steps){let d=document.getElementById('rxtour');if(!d){d=document.createElement('div');d.id='rxtour';d.className='rxtour';document.body.appendChild(d)}let i=0;
 const go=()=>{const s=steps[i];document.querySelectorAll('.rxhl').forEach(e=>e.classList.remove('rxhl'));const el=document.getElementById(s.id);if(el){el.classList.add('rxhl');const y=el.getBoundingClientRect().top+scrollY-24;scrollTo({top:y,behavior:'smooth'})}
  d.innerHTML=`<div class="hd"><small>${L(RXL.tour)} · ${L(RXL.step).replace('%A',i+1).replace('%B',steps.length)}</small><button type="button" data-a="x">${L(RXL.close)} ✕</button></div><h4>${L(s.t)}</h4><p>${L(s.p)}</p><div class="ft"><div class="dots">${steps.map((_,j)=>`<u class="${j===i?'on':''}"></u>`).join('')}</div><div>${i?`<button type="button" data-a="p">← ${L(RXL.prev)}</button> `:''}<button type="button" class="p" data-a="n">${i===steps.length-1?L(RXL.end):L(RXL.next)+' →'}</button></div></div>`;d.classList.add('on')};
 d.onclick=e=>{const a=e.target.dataset.a;if(!a)return;if(a==='x'||(a==='n'&&i===steps.length-1)){d.classList.remove('on');document.querySelectorAll('.rxhl').forEach(e=>e.classList.remove('rxhl'));return}i+=a==='n'?1:-1;go()};
 go()}
// wrap module list: ids for the tour, explainer in each module
function enrich(mods,keys,EXS,pre){return mods.map((m,j)=>{const k=keys[j];return [m[0],withEX(m[1],EXS[k]),m[2]||pre+k]})}

