 i_gift:['Gift memberships sold a month','Uanachama wa zawadi unaouzwa kwa mwezi'],i_gm:['Average months per gift','Wastani wa miezi kwa kila zawadi'],i_ren:['Recipients who renew after the gift','Wapokeaji wanaoendelea baada ya zawadi'],i_dia:['Families on Care from afar (average in the year)','Familia kwenye Huduma ukiwa mbali (wastani wa mwaka)'],i_fleet:['Rental units in the fleet','Vifaa vya kukodisha'],i_corp:['Corporate clients (25 staff each)','Wateja wa makampuni (wafanyakazi 25 kila mmoja)'],
