const CSS7X=`
.r7cm{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:4px;margin-top:20px}
.r7cm button{border:1px solid var(--l);border-radius:10px;background:var(--c);color:var(--i);padding:10px 0;cursor:pointer;font:500 .9rem inherit}
.r7cm button.on{border-color:var(--g);background:linear-gradient(170deg,#262012,#0e0d0a)}
.r7cx{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,1fr);gap:24px;margin-top:18px;align-items:start}
.r7cx .r7kb{aspect-ratio:16/10}
.r7cx h4{margin:0;font:400 1.9rem/1.12 var(--f-serif,Georgia,serif);color:var(--i)}.r7cx h4 small{display:block;margin-bottom:8px;font:600 .66rem var(--f-hud,monospace);letter-spacing:.15em;text-transform:uppercase;color:var(--g)}
.r7cg{display:grid;gap:10px;margin-top:14px}.r7cg div{padding:12px 16px;border-radius:12px;background:var(--c);border:1px solid var(--l)}.r7cg small{display:block;font:600 .6rem var(--f-hud,monospace);letter-spacing:.14em;text-transform:uppercase;color:var(--g2)}.r7cg p{margin:5px 0 0;font:400 1rem/1.6 var(--f-serif,Georgia,serif);color:rgba(247,242,232,.88)}
.r7cg div.t{background:linear-gradient(120deg,#1d2a20,#0f1211);border-color:rgba(127,214,194,.3)}.r7cg div.t p{color:#bfeee2}
.r7af{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.05fr);gap:24px;margin-top:22px;align-items:start}
.r7svc{display:grid;gap:6px}.r7svc label{display:flex;justify-content:space-between;gap:10px;align-items:center;padding:9px 12px;border-radius:10px;background:var(--c);border:1px solid var(--l);font-size:.94rem;color:rgba(247,242,232,.88);cursor:pointer}.r7svc label em{font-style:normal;font:500 .8rem var(--f-hud,monospace);color:var(--g2);white-space:nowrap}.r7svc input{width:18px;height:18px;accent-color:#d8b46a;flex:0 0 auto}
.r7ph{margin-top:16px;max-width:380px;border-radius:28px;padding:14px;background:#050606;border:1px solid rgba(255,255,255,.12);box-shadow:0 20px 50px rgba(0,0,0,.5)}
.r7ph .sc{border-radius:18px;background:#0f1a15;padding:16px}.r7ph small{font:600 .6rem var(--f-hud,monospace);letter-spacing:.14em;text-transform:uppercase;color:#7fd6c2}.r7ph b{display:block;margin-top:6px;font:400 1.15rem var(--f-serif,Georgia,serif);color:#fff}
.r7ph ul{margin:12px 0 0;padding:0;list-style:none}.r7ph li{display:flex;gap:10px;padding:8px 0;border-top:1px solid rgba(255,255,255,.08);font-size:.9rem;line-height:1.45;color:rgba(255,255,255,.85)}.r7ph li i{font-style:normal;color:#7fd6c2}
.r7fl input[type=number]{width:64px;box-sizing:border-box;background:rgba(0,0,0,.35);border:1px solid var(--l);border-radius:8px;padding:6px 8px;color:var(--i);font:500 .92rem var(--f-hud,monospace);text-align:right}
@media(max-width:1000px){.r7cx,.r7af{grid-template-columns:1fr}.r7cm{grid-template-columns:repeat(6,1fr)}}`;

function enrich7(mods){rxcss();if(!document.getElementById('r7x-css')){const e=document.createElement('style');e.id='r7x-css';e.textContent=CSS7X;document.head.appendChild(e)}
 const X=k=>L(UX7[k]);const MN=[['Jan','Jan'],['Feb','Feb'],['Mar','Mac'],['Apr','Apr'],['May','Mei'],['Jun','Jun'],['Jul','Jul'],['Aug','Ago'],['Sep','Sep'],['Oct','Okt'],['Nov','Nov'],['Dec','Des']];
 const camp=[X('m_camp'),`<p class="ld">${X('camp_ld')}</p><div class="r7cm" id="r7cm">${MN.map((m,i)=>`<button type="button" data-i="${i}">${L(m)}</button>`).join('')}</div><div class="r7cx" id="r7cx"></div>`];
 const afar=[X('m_afar'),`<p class="ld">${X('afar_ld')}</p><div class="r7af"><div id="r7ai"></div><div id="r7ao"></div></div>`];
 const [films,room,gift,pool,rent,imp]=mods;
 const rent2=[rent[0],rent[1]+`<h5 class="hud" style="margin:28px 0 8px;color:var(--g)">${X('m_fleet')}</h5><p class="nt" style="margin:0 0 10px">${X('fl_ld')}</p><div class="r7fl" id="r7fl"></div>`,rent[2]];
 EX7.give=EXG;return enrich([films,room,camp,gift,pool,giveHTML(),afar,rent2,imp],['films','room','camp','gift','pool','give','afar','rent','imp'],EX7,'r7m-')}
function hero7(){return heroStats([[IDEAS.length,L(UX7.hs[0])],[12,L(UX7.hs[1])],[RENT.length,L(UX7.hs[2])],[8,L(UX7.hs[3])]])+`<button type="button" class="rxtb" id="r7tour"><i></i>${L(RXL.tour)}</button>`}
function init7x(){const g=id=>document.getElementById(id);countUp();g('r7tour').onclick=()=>tour(TOUR7.map(x=>({id:x[0],t:x[1],p:x[2]})));camp7();give7();afar7();fleet7()}

let CM=new Date().getMonth();
function camp7(){const g=id=>document.getElementById(id);const X=k=>L(UX7[k]);
 const paint=()=>{const c=CAMP[CM];g('r7cm').querySelectorAll('button').forEach(b=>b.classList.toggle('on',+b.dataset.i===CM));
  g('r7cx').innerHTML=`<div class="r7kb"><img src="img/${c.img}.webp" alt="Concept image for the campaign ${E(c.n[0])}"><i class="sh"></i><div class="cap"><small>${E(L(c.d))}</small><h3>${E(L(c.n))}</h3></div></div><div><h4><small>${E(L(c.d))}</small>${E(L(c.n))}</h4><div class="r7cg"><div><small>${X('offer')}</small><p>${E(L(c.o))}</p></div><div><small>${X('chan')}</small><p>${E(L(c.c))}</p></div><div><small>${X('tgt')}</small><p>${E(L(c.t))}</p></div><div class="t"><small>${X('give')}</small><p>${E(L(c.s))}</p></div></div></div>`};
 g('r7cm').querySelectorAll('button').forEach(b=>b.onclick=()=>{CM=+b.dataset.i;paint()});paint()}

const AF={c:0,lv:0,t:'E',sib:3,sv:{}};
const AFC=[['senior',['Elderly care','Huduma ya wazee']],['presha',['High blood pressure','Shinikizo la damu']],['sugar',['Diabetes','Kisukari']]];
function afar7(){const g=id=>document.getElementById(id);const X=k=>L(UX7[k]);
 const inp=()=>{const pk=AFC[AF.c][0],st=D.PKG[pk].stages;if(AF.lv>=st.length)AF.lv=0;const tiers=(A.msOk(pk)?['M']:[]).concat(['E','C','L']);
  const sv=A.services(pk).filter(x=>(x.w==='partner'||x.w==='option')&&x.member);const sn=x=>Array.isArray(x.n)?L(x.n):(lang()&&SW.svc[x.n]?SW.svc[x.n][2]:x.n);
  g('r7ai').innerHTML=`<div class="r7f"><span>${X('cond')}</span><div class="r7seg" id="r7ac">${AFC.map((c,i)=>`<button type="button" data-i="${i}" class="${i===AF.c?'on':''}">${L(c[1])}</button>`).join('')}</div></div>
  ${st.length>1?`<div class="r7f"><span>${X('lvl')}</span><div class="r7seg" id="r7al">${st.map((s,i)=>`<button type="button" data-i="${i}" class="${i===AF.lv?'on':''}">${E(stN(s))}</button>`).join('')}</div></div>`:''}
  <div class="r7f"><span>${L(['Edition','Toleo'])}</span><div class="r7seg" id="r7at">${tiers.map(t=>`<button type="button" data-t="${t}" class="${t===AF.t?'on':''}">${L(TIERN[t])}</button>`).join('')}</div></div>
  <label class="r7sl"><span>${X('sib')}<output>${AF.sib}</output></span><input type="range" id="r7as" min="1" max="6" value="${AF.sib}"></label>
  <div class="r7f"><span>${X('extra')}</span><div class="r7svc">${sv.map((x,i)=>`<label><span><input type="checkbox" data-i="${i}" ${AF.sv[pk+i]?'checked':''}> ${E(sn(x))}</span><em>${T(x.member)}</em></label>`).join('')}</div></div>`;
  g('r7ac').querySelectorAll('button').forEach(b=>b.onclick=()=>{AF.c=+b.dataset.i;AF.lv=0;inp()});
  if(g('r7al'))g('r7al').querySelectorAll('button').forEach(b=>b.onclick=()=>{AF.lv=+b.dataset.i;inp()});
  g('r7at').querySelectorAll('button').forEach(b=>b.onclick=()=>{AF.t=b.dataset.t;inp()});
  g('r7as').oninput=e=>{AF.sib=+e.target.value;e.target.previousElementSibling.querySelector('output').textContent=AF.sib;out()};
  g('r7ai').querySelectorAll('.r7svc input').forEach(c=>c.onchange=e=>{AF.sv[pk+e.target.dataset.i]=e.target.checked;out()});
  if(!tiers.includes(AF.t))AF.t='E';out()};
 const out=()=>{const pk=AFC[AF.c][0],s=D.PKG[pk].stages[AF.lv],box=A.stage(pk,s.k,AF.t,12).month.box;const sv=A.services(pk).filter(x=>(x.w==='partner'||x.w==='option')&&x.member);
  const svt=sv.reduce((t,x,i)=>t+(AF.sv[pk+i]?x.member:0),0),tot=box+svt;
  g('r7ao').innerHTML=`<div class="r7rc" style="margin-top:0"><div class="hd"><div><small>${X('each')}</small><b>${T(Math.ceil(tot/AF.sib/500)*500)}</b></div><div><small>${X('mtot')}</small><b>${T(tot)}</b></div><div><small>${X('year')}</small><b>${TM(tot*12)}</b></div></div><ul><li><span>${X('mbox')} · ${E(L(AFC[AF.c][1]))} · ${E(stN(s))} · ${L(TIERN[AF.t])}</span><em>${T(box)}</em></li><li><span>${X('msvc')}</span><em>${T(svt)}</em></li></ul></div>
  <div class="r7ph"><div class="sc"><small>Afya Basics · ${X('rep')}</small><b>${lang()?'Mama, Sinza · Machi':'Mama, Sinza · March'}</b><span style="font-size:.8rem;color:rgba(255,255,255,.6)">${X('rep_to')} (${AF.sib})</span><ul><li><i>✓</i>${X('r1')}</li><li><i>✓</i>${X('r2')}</li><li><i>✓</i>${X('r3')}</li><li><i>→</i>${X('r4')}</li></ul></div></div>`};
 inp()}

function fleetCalc(F){const util=S7.util/100;let cap=0,inc=0,pro=0,hh=0,u=0;RENT.forEach(r=>{const n=F[r.k]||0;if(!n)return;const f=fee(r),rw=52*util,rn=rw/r.w;u+=n;cap+=n*buyP(r)*R_COST;inc+=n*f*rw;pro+=n*(f*rw-R_CLEAN*rn-buyP(r)*R_COST/R_LIFE);hh+=n*rn});return {cap,inc,pro,hh,u,pb:cap/((inc-0)/12-(0))}}
let FLEET=Object.assign({},FLEET0);
function fleet7(){const g=id=>document.getElementById(id);const X=k=>L(UX7[k]);if(!g('r7fl'))return;
 const paint=()=>{const c=fleetCalc(FLEET);const util=S7.util/100;const cl=RENT.reduce((t,r)=>t+(FLEET[r.k]||0)*R_CLEAN*52*util/r.w,0);const pb=c.cap/((c.inc-cl)/12);
  g('r7flo').innerHTML=`<div class="r7nums" style="margin-top:0"><div><b>${TM(c.cap)}</b><span>${X('cap')}</span></div><div class="g"><b>${TM(c.inc)}</b><span>${X('finc')}</span></div><div class="g"><b>${TM(c.pro)}</b><span>${X('fpro')}</span></div><div><b>${c.u?U('mo_').replace('%N',pb.toFixed(1)):'–'}</b><span>${X('fpb')}</span></div></div><p class="nt">${X('fhh')}: <b>${NF(c.hh)}</b> · ${U('util')}: <b>${S7.util}%</b></p>`;
  if(window.__r7imp)window.__r7imp()};
 g('r7fl').innerHTML=`<div style="overflow-x:auto"><table class="r7tbl"><thead><tr><th>${lang()?'Kifaa':'Item'}</th><th class="n">${U('fee')}</th><th class="n">${X('typ')}</th><th class="n">${X('units')}</th></tr></thead><tbody>${RENT.map(r=>`<tr><td>${E(L(r.n))}</td><td class="n">${T(fee(r))}</td><td class="n">${X('wk').replace('%N',r.w)}</td><td class="n"><input type="number" min="0" max="50" value="${FLEET[r.k]||0}" data-k="${r.k}" aria-label="${E(L(r.n))}"></td></tr>`).join('')}</tbody></table></div><div id="r7flo" style="margin-top:14px"></div>`;
 g('r7fl').querySelectorAll('input').forEach(i=>i.oninput=e=>{FLEET[e.target.dataset.k]=Math.max(0,Math.min(50,+e.target.value||0));paint()});
 window.__r7fleet=paint;paint()}
